// Configures Meilisearch (indexes, settings, embedder, chat workspace) and imports
// ../data/episodes.json + ../data/chunks.ndjson.
//
//   node scripts/setup-meilisearch.ts            # embeddings keep computing in the background
//   node scripts/setup-meilisearch.ts --wait     # wait until every chunk is embedded
//
// If ../data/chunks-with-vectors.ndjson exists (see export-vectors.ts), documents are imported
// with their precomputed embeddings and the target instance never re-embeds anything.
import { Meilisearch } from "meilisearch";
import { createReadStream, existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { createInterface } from "node:readline";
import { gzipSync } from "node:zlib";
import type { Chunk, Episode } from "../src/lib/types.ts";
import { loadEnv } from "./env.ts";

loadEnv();

const host = process.env.MEILI_HOST ?? "http://localhost:7710";
const apiKey = [REDACTED] ?? "talk-with-lex-master-key-change-me";
const client = new Meilisearch({ host, apiKey });
const DATA = path.resolve(import.meta.dirname, "../../data");

const CHUNKS = process.env.MEILI_CHUNKS_INDEX ?? "chunks";
const EPISODES = process.env.MEILI_EPISODES_INDEX ?? "episodes";
const EMBEDDER = "default";
const WORKSPACE = process.env.CHAT_WORKSPACE ?? "lex";
const BATCH_PLAIN = 10_000;
const VECTORS_FILE = path.join(DATA, "chunks-with-vectors.ndjson");
const withVectors = existsSync(VECTORS_FILE);
// Documents with 384-float vectors are ~9x bigger: smaller batches, gzipped, stay under the payload limit.
const BATCH = withVectors ? 5_000 : BATCH_PLAIN;

async function addBatch(docs: Chunk[]): Promise<number> {
  if (!withVectors) return (await client.index<Chunk>(CHUNKS).addDocuments(docs)).taskUid;
  const body = gzipSync(docs.map((d) => JSON.stringify(d)).join("\n"));
  const task = (await meili(`/indexes/${CHUNKS}/documents?primaryKey=id`, {
    method: "POST",
    headers: { "Content-Type": "application/x-ndjson", "Content-Encoding": "gzip" },
    body,
  })) as { taskUid: number };
  return task.taskUid;
}

async function meili(pathname: string, init: RequestInit = {}) {
  const res = await fetch(`${host}${pathname}`, {
    ...init,
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json", ...init.headers },
  });
  if (!res.ok) throw new Error(`${init.method ?? "GET"} ${pathname} -> ${res.status} ${await res.text()}`);
  return res.status === 204 ? null : res.json();
}

async function waitTask(taskUid: number, label: string) {
  const started = Date.now();
  const task = await client.tasks.waitForTask(taskUid, { timeout: 6 * 60 * 60 * 1000, interval: 2000 });
  if (task.status !== "succeeded") throw new Error(`${label} failed: ${JSON.stringify(task.error)}`);
  console.log(`✓ ${label} (${((Date.now() - started) / 1000).toFixed(1)}s)`);
}

function embedderSettings() {
  const source = process.env.EMBEDDER_SOURCE ?? "huggingFace";
  // The speaker + chapter give the vector some context beyond the raw words.
  const documentTemplate =
    "{% if doc.speaker %}{{doc.speaker}}: {% endif %}{{doc.text}}{% if doc.chapter %} (topic: {{doc.chapter}}){% endif %}";
  if (source === "openAi") {
    if (!process.env.EMBEDDER_API_KEY) throw new Error("EMBEDDER_SOURCE=openAi requires EMBEDDER_API_KEY");
    return {
      source: "openAi",
      apiKey: [REDACTED],
      model: "text-embedding-3-small",
      dimensions: 1536,
      documentTemplate,
      documentTemplateMaxBytes: 2000,
    };
  }
  return { source: "huggingFace", model: "BAAI/bge-small-en-v1.5", documentTemplate, documentTemplateMaxBytes: 2000 };
}

const CHAT_DESCRIPTION =
  "Chunked transcripts of the Lex Fridman Podcast (≈400 long-form conversations about AI, science, history, politics, philosophy, sports and more). Each document is ~1 minute of the conversation with the episode title, guest, speaker (when known), chapter and timestamp.";

const CHAT_TEMPLATE =
  "Episode: {{doc.episodeTitle}}\nGuest: {{doc.guest}}\n{% if doc.speaker %}Speaker: {{doc.speaker}}\n{% endif %}{% if doc.chapter %}Chapter: {{doc.chapter}}\n{% endif %}Timestamp: {{doc.timestamp}}\nLink: https://www.youtube.com/watch?v={{doc.episodeId}}&t={{doc.start}}s\nTranscript: {{doc.text}}";

async function main() {
  const episodes: Episode[] = JSON.parse(await readFile(path.join(DATA, "episodes.json"), "utf8"));

  await meili("/experimental-features", { method: "PATCH", body: JSON.stringify({ chatCompletions: true }) });
  console.log("✓ experimental feature: chatCompletions");

  // ---- chunks index: settings without the embedder first, so keyword search works right away
  await client.createIndex(CHUNKS, { primaryKey: "id" }).waitTask().catch(() => undefined);
  const chunks = client.index<Chunk>(CHUNKS);
  const baseSettings = {
    searchableAttributes: ["text", "speaker", "guest", "chapter", "episodeTitle"],
    displayedAttributes: ["*"],
    filterableAttributes: ["episodeId", "episodeNumber", "guest", "speaker", "isLex", "source", "position", "start"],
    sortableAttributes: ["episodeNumber", "start", "position"],
    rankingRules: ["words", "typo", "proximity", "attribute", "sort", "exactness"],
    typoTolerance: { minWordSizeForTypos: { oneTypo: 5, twoTypos: 9 } },
    synonyms: {
      agi: ["artificial general intelligence"],
      "artificial general intelligence": ["agi"],
      ai: ["artificial intelligence"],
      llm: ["large language model"],
      llms: ["large language models"],
      bjj: ["jiu jitsu"],
      "jiu jitsu": ["bjj", "jiu-jitsu"],
      ussr: ["soviet union"],
      "soviet union": ["ussr"],
    },
    faceting: { maxValuesPerFacet: 500, sortFacetValuesBy: { "*": "count" } },
    pagination: { maxTotalHits: 1000 },
    chat: {
      description: CHAT_DESCRIPTION,
      documentTemplate: CHAT_TEMPLATE,
      documentTemplateMaxBytes: 2000,
      searchParameters: { limit: 12 },
    },
  };
  const hybridChat = {
    ...baseSettings.chat,
    searchParameters: { limit: 12, hybrid: { embedder: EMBEDDER, semanticRatio: 0.6 } },
  };
  // With precomputed vectors the embedder must exist before the documents arrive (they carry
  // `regenerate: false`), so the whole configuration goes in at once.
  const firstSettings = withVectors
    ? { ...baseSettings, embedders: { [EMBEDDER]: embedderSettings() }, chat: hybridChat }
    : baseSettings;
  await waitTask(
    (await chunks.updateSettings(firstSettings as Parameters<typeof chunks.updateSettings>[0])).taskUid,
    withVectors ? "chunks settings + embedder" : "chunks settings",
  );

  // ---- import chunks in batches (the NDJSON file is ~90 MB) --------------
  let batch: Chunk[] = [];
  let total = 0;
  let lastTask = 0;
  const importFile = withVectors ? VECTORS_FILE : path.join(DATA, "chunks.ndjson");
  console.log(`… importing ${path.basename(importFile)}`);
  const lines = createInterface({ input: createReadStream(importFile) });
  for await (const line of lines) {
    if (!line.trim()) continue;
    batch.push(JSON.parse(line));
    if (batch.length === BATCH) {
      lastTask = await addBatch(batch);
      total += batch.length;
      batch = [];
      process.stdout.write(`\r  sent ${total.toLocaleString()}`);
    }
  }
  if (batch.length) {
    lastTask = await addBatch(batch);
    total += batch.length;
  }
  await waitTask(lastTask, `chunks documents (${total.toLocaleString()})`);

  // ---- episodes index (multi-search + guest lookup) -----------------------
  await client.createIndex(EPISODES, { primaryKey: "id" }).waitTask().catch(() => undefined);
  const episodesIndex = client.index<Episode>(EPISODES);
  await waitTask(
    (
      await episodesIndex.updateSettings({
        searchableAttributes: ["guest", "topic", "title", "tagline", "chapters.title"],
        filterableAttributes: ["id", "source", "episodeNumber", "guest"],
        sortableAttributes: ["episodeNumber"],
        displayedAttributes: ["id", "episodeNumber", "title", "guest", "topic", "tagline", "source", "durationSec", "chunkCount", "speakers"],
      })
    ).taskUid,
    "episodes settings",
  );
  await waitTask((await episodesIndex.addDocuments(episodes)).taskUid, `episodes documents (${episodes.length})`);

  // ---- chat workspace ----------------------------------------------------
  const chatKey = process.env.CHAT_API_KEY;
  const source = process.env.CHAT_SOURCE ?? "openAi";
  if (chatKey || source === "vLlm") {
    await meili(`/chats/${WORKSPACE}/settings`, {
      method: "PATCH",
      body: JSON.stringify({
        source,
        apiKey: chatKey || undefined,
        baseUrl: process.env.CHAT_BASE_URL || undefined,
        prompts: {
          system: [
            "You are an expert on the Lex Fridman Podcast. Answer using ONLY the transcript excerpts returned by your search tool; never rely on outside knowledge about what someone said.",
            "Every claim must be cited with a Markdown link to the exact moment, using the Link field of the excerpt, e.g. [Elon Musk, #400 at 1:02:03](https://www.youtube.com/watch?v=ID&t=3723s).",
            "Quote short verbatim fragments when the user asks what someone said. Excerpts without a Speaker field come from automatic transcripts where the speaker is unknown: say so if it matters.",
            "Search several times with different phrasings when the first search is not conclusive. If the excerpts do not contain the answer, say you could not find it in the transcripts. Use concise Markdown.",
          ].join(" "),
          searchDescription:
            "Search the Lex Fridman Podcast transcripts. Use it for any question about what Lex or a guest said, which episode discussed a topic, or opinions expressed on the show.",
          searchQParam:
            "Search query: the key words or a short paraphrase of what was said (e.g. `meaning of life`, `love is the answer`). Not a full question.",
          searchFilterParam:
            "Optional Meilisearch filter. Examples: `isLex = true` (only Lex's own words, recent episodes), `guest = \"Elon Musk\"`, `speaker = \"Elon Musk\"`, `episodeNumber >= 400`. Leave empty unless the user explicitly restricts who spoke or which episode.",
          searchIndexUidParam: `Index to search. Always use \`${CHUNKS}\`.`,
        },
      }),
    });
    console.log(`✓ chat workspace "${WORKSPACE}" (${source})`);
  } else {
    console.log("! CHAT_API_KEY not set: chat workspace skipped (search still works)");
  }

  if (withVectors) {
    console.log("✓ embeddings imported from chunks-with-vectors.ndjson (no re-embedding)");
    return;
  }

  // ---- embedder last: it re-embeds every chunk, which is the long part ---
  const embedder = embedderSettings();
  const embedTask = await chunks.updateSettings({
    embedders: { [EMBEDDER]: embedder },
    chat: hybridChat,
  } as Parameters<typeof chunks.updateSettings>[0]);
  console.log(`… embedding ${total.toLocaleString()} chunks with ${embedder.source} ${embedder.model} (task ${embedTask.taskUid})`);
  if (process.argv.includes("--wait")) {
    await waitTask(embedTask.taskUid, "embeddings");
  } else {
    console.log("  Keyword search works now; semantic search and chat turn on when the task finishes.");
    console.log(`  Follow it with: curl -s -H 'Authorization: Bearer $MEILI_MASTER_KEY' ${host}/tasks/${embedTask.taskUid}`);
  }
}

await main();

"use client";

import { create } from "zustand";
import type { SearchRequest, SortOption, SpeakerFilter } from "@/lib/types";

interface SearchState extends SearchRequest {
  setQ: (q: string) => void;
  setSort: (s: SortOption) => void;
  setPage: (p: number) => void;
  setSpeaker: (s: SpeakerFilter) => void;
  toggleGuest: (guest: string) => void;
  setEpisode: (episodeId?: string) => void;
  setDistinct: (distinct: boolean) => void;
  clearFilters: () => void;
}

export const useSearch = create<SearchState>()((set) => ({
  q: "",
  page: 1,
  sort: "relevance",
  speaker: "all",
  guests: [],
  episodeId: undefined,
  distinct: false,
  setQ: (q) => set({ q, page: 1 }),
  setSort: (sort) => set({ sort, page: 1 }),
  setPage: (page) => set({ page }),
  setSpeaker: (speaker) => set({ speaker, page: 1 }),
  toggleGuest: (guest) =>
    set((s) => ({
      guests: s.guests.includes(guest) ? s.guests.filter((g) => g !== guest) : [...s.guests, guest],
      page: 1,
    })),
  // Opening one episode shows all its moments, so grouping by episode no longer makes sense.
  setEpisode: (episodeId) => set((s) => ({ episodeId, distinct: episodeId ? false : s.distinct, page: 1 })),
  setDistinct: (distinct) => set({ distinct, page: 1 }),
  clearFilters: () => set({ speaker: "all", guests: [], episodeId: undefined, page: 1 }),
}));

"use client";

import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Layers, Loader2, Mic, Search, Sparkles, X } from "lucide-react";
import { useDeferredValue } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { SEMANTIC_RATIO, type SearchResponse, type SortOption } from "@/lib/types";
import { cn } from "@/lib/utils";
import { FiltersPanel } from "./filters-panel";
import { QuoteCard } from "./quote-card";
import { useSearch } from "./search-store";

export interface Status {
  chatEnabled: boolean;
  chatModel: string;
  chunkCount: number;
  episodeCount: number;
  semanticReady: boolean;
}

const SORTS: { value: SortOption; label: string }[] = [
  { value: "relevance", label: "Relevance" },
  { value: "newest", label: "Newest" },
  { value: "oldest", label: "Oldest" },
];

const EXAMPLES = [
  '"love is the answer"',
  "meaning of life",
  "fear of death",
  "is AGI going to kill us",
  "jiu jitsu teaches humility",
  "Dostoevsky", // typo-tolerant too: try "Dostoyevski"
];

export function SearchPage() {
  const state = useSearch();
  const request = useDeferredValue({
    q: state.q,
    page: state.page,
    sort: state.sort,
    speaker: state.speaker,
    guests: state.guests,
    episodeId: state.episodeId,
    distinct: state.distinct,
  });

  const { data: status } = useQuery({
    queryKey: ["status"],
    queryFn: async (): Promise<Status> => (await fetch("/api/status")).json(),
    refetchInterval: (query) => (query.state.data?.semanticReady ? false : 15_000),
  });
  const { data, isFetching, isError, error } = useQuery({
    queryKey: ["search", request],
    queryFn: async (): Promise<SearchResponse & { semantic: boolean }> => {
      const res = await fetch("/api/search", { method: "POST", body: JSON.stringify(request) });
      if (res.status === 503) throw new Error("loading");
      if (!res.ok) throw new Error("Search failed");
      return res.json();
    },
    placeholderData: keepPreviousData,
    // While the archive is loading, retry every 20 s so the page comes alive on its own.
    refetchInterval: (query) => (query.state.error ? 20_000 : false),
    retry: (count, error) => error.message !== "loading" && count < 2,
  });

  // Semantic search ranks every chunk, so the total count isn't meaningful: cap paging instead.
  const semantic = !!data?.semantic;
  const grouped = request.distinct;
  const focused = data?.hits[0] && state.episodeId ? data.hits[0] : undefined;
  const totalPages = data ? (semantic ? Math.min(data.totalPages, 10) : data.totalPages) : 0;

  return (
    <main className="mx-auto w-full max-w-7xl flex-1 px-4 pb-24">
      <section className="py-8">
        <h1 className="font-serif text-3xl font-semibold tracking-tight sm:text-4xl">Where did Lex say that?</h1>
        <p className="mt-1 text-muted-foreground">
          Search {status ? status.episodeCount.toLocaleString() : "…"} episodes of the Lex Fridman Podcast, cut into{" "}
          {status ? status.chunkCount.toLocaleString() : "…"} one-minute passages, and jump straight to the moment.
        </p>

        <div className="relative mt-5">
          <Search className="absolute top-1/2 left-4 size-5 -translate-y-1/2 text-muted-foreground" />
          <Input
            autoFocus
            value={state.q}
            onChange={(e) => state.setQ(e.target.value)}
            placeholder='A quote, an idea, a name… use "double quotes" for an exact phrase'
            className="h-12 rounded-xl pl-12 text-base shadow-sm md:text-base"
          />
          {data && (
            <span className="absolute top-1/2 right-4 -translate-y-1/2 font-mono text-xs text-muted-foreground">
              {data.processingTimeMs} ms
            </span>
          )}
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-3">
          <div className="flex items-center gap-2">
            <Sparkles className="size-4 text-[var(--brand)]" />
            {status && !status.semanticReady ? (
              <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Loader2 className="size-3 animate-spin" /> Embeddings are still computing: keyword search for now
              </span>
            ) : (
              <span className="text-sm">
                <span className="font-medium">Hybrid search</span>
                <span className="ml-1 text-muted-foreground">keywords + meaning</span>
                <span className="ml-1.5 font-mono text-xs text-muted-foreground">semanticRatio={SEMANTIC_RATIO}</span>
              </span>
            )}
          </div>
          {!state.q && (
            <div className="flex flex-wrap items-center gap-1.5 text-sm">
              <span className="text-muted-foreground">Try:</span>
              {EXAMPLES.map((ex) => (
                <button
                  key={ex}
                  onClick={() => state.setQ(ex)}
                  className="rounded-full border px-2.5 py-0.5 text-xs transition-colors hover:border-[var(--brand)] hover:text-[var(--brand)]"
                >
                  {ex}
                </button>
              ))}
            </div>
          )}
        </div>
      </section>

      <div className="grid gap-8 lg:grid-cols-[250px_1fr]">
        <FiltersPanel data={data} />

        <section className="min-w-0 space-y-4">
          {data && data.episodes.length > 0 && (
            <div className="flex flex-wrap items-center gap-2 rounded-xl border border-dashed p-3">
              <span className="text-xs text-muted-foreground">Episodes with “{state.q}”</span>
              {data.episodes.map((e) => (
                <button
                  key={e.id}
                  onClick={() => state.toggleGuest(e.guest)}
                  className="flex items-center gap-1.5 rounded-full bg-muted px-2.5 py-1 text-xs hover:bg-muted/70"
                >
                  <Mic className="size-3" />
                  {e.episodeNumber ? `#${e.episodeNumber} ` : ""}
                  {e.guest}
                  <span className="max-w-48 truncate text-muted-foreground">{e.topic}</span>
                </button>
              ))}
            </div>
          )}

          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-sm text-muted-foreground">
              {data ? (
                semantic ? (
                  <>
                    {grouped ? "Best moment of each episode" : "Best matches"}, ranked by meaning + keywords
                    {!!data.semanticHitCount && (
                      <>
                        {" "}·{" "}
                        <span className="inline-flex items-center gap-1.5">
                          <span className="inline-block size-3 rounded-[4px] border-2 border-[var(--brand)]/35" />
                          {data.semanticHitCount} found by meaning
                        </span>
                      </>
                    )}
                  </>
                ) : (
                  <>
                    <span className="font-medium text-foreground">{data.totalHits.toLocaleString()}</span>{" "}
                    {grouped ? "episodes" : state.q ? "moments" : "passages"}
                  </>
                )
              ) : (
                "Searching…"
              )}
            </p>
            <div className="flex items-center gap-2">
            <button
              onClick={() => state.setDistinct(!state.distinct)}
              aria-pressed={state.distinct}
              title="Meilisearch distinct on episodeId: keep only the best moment of each episode"
              className={cn(
                "flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-xs text-muted-foreground transition-colors hover:text-foreground",
                state.distinct && "border-[var(--brand)] bg-[var(--brand)]/10 text-foreground",
              )}
            >
              <Layers className="size-3.5" />
              One per episode
            </button>
            <div className="flex rounded-lg border p-0.5">
              {SORTS.map((s) => (
                <button
                  key={s.value}
                  onClick={() => state.setSort(s.value)}
                  className={cn(
                    "rounded-md px-2.5 py-1 text-xs text-muted-foreground transition-colors",
                    state.sort === s.value && "bg-muted text-foreground",
                  )}
                >
                  {s.label}
                </button>
              ))}
            </div>
            </div>
          </div>

          {state.episodeId && (
            <div className="flex items-center gap-2 text-sm">
              <span className="flex items-center gap-1.5 rounded-full bg-muted py-1 pr-1.5 pl-3">
                Only in {focused ? `${focused.episodeNumber ? `#${focused.episodeNumber} ` : ""}${focused.guest}` : "this episode"}
                <button onClick={() => state.setEpisode(undefined)} aria-label="Search every episode">
                  <X className="size-3.5" />
                </button>
              </span>
            </div>
          )}

          {isError &&
            (error?.message === "loading" ? (
              <p className="flex items-center gap-2 rounded-lg border border-amber-500/40 bg-amber-500/10 p-3 text-sm">
                <Loader2 className="size-4 animate-spin" />
                The transcripts are being loaded into Meilisearch. This page will work in a few minutes.
              </p>
            ) : (
              <p className="text-sm text-destructive">Search failed. Is Meilisearch running?</p>
            ))}

          <div className={cn("grid gap-3 transition-opacity", isFetching && "opacity-60")}>
            {!data
              ? Array.from({ length: 5 }, (_, i) => <Skeleton key={i} className="h-36 rounded-xl" />)
              : data.hits.map((hit) => <QuoteCard
                    key={hit.id}
                    hit={hit}
                    onGuest={state.toggleGuest}
                    moreMoments={grouped ? (data.momentsPerEpisode?.[hit.episodeId] ?? 1) - 1 : 0}
                    onEpisode={state.setEpisode}
                  />)}
            {data && data.hits.length === 0 && (
              <p className="py-12 text-center text-muted-foreground">
                Nothing found. Try fewer words, or describe the idea in your own words.
              </p>
            )}
          </div>

          {data && totalPages > 1 && (
            <div className="flex items-center justify-center gap-3 pt-2">
              <Button variant="outline" size="sm" disabled={state.page <= 1} onClick={() => state.setPage(state.page - 1)}>
                <ChevronLeft /> Previous
              </Button>
              <span className="font-mono text-xs text-muted-foreground">
                {data.page} / {totalPages}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={state.page >= totalPages}
                onClick={() => state.setPage(state.page + 1)}
              >
                Next <ChevronRight />
              </Button>
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

import { NextResponse } from "next/server";
import { CHAT_MODEL, chatEnabled, CHUNKS_INDEX, EPISODES_INDEX, meili, semanticReady } from "@/lib/meili";

export async function GET() {
  const [chat, chunks, episodes, semantic] = await Promise.all([
    chatEnabled(),
    meili.index(CHUNKS_INDEX).getStats().catch(() => null),
    meili.index(EPISODES_INDEX).getStats().catch(() => null),
    semanticReady(),
  ]);
  return NextResponse.json({
    chatEnabled: chat,
    chatModel: CHAT_MODEL,
    chunkCount: chunks?.numberOfDocuments ?? 0,
    episodeCount: episodes?.numberOfDocuments ?? 0,
    semanticReady: semantic,
  });
}

import { NextResponse } from "next/server";
import { CHUNKS_INDEX, meili } from "@/lib/meili";

/** Type-ahead over the ~400 guests, counts reflect the current query. */
export async function POST(req: Request) {
  const { facetQuery, q } = (await req.json()) as { facetQuery: string; q?: string };
  const res = await meili.index(CHUNKS_INDEX).searchForFacetValues({ facetName: "guest", facetQuery, q });
  return NextResponse.json(res.facetHits);
}

import { NextResponse } from "next/server";
import { CHUNKS_INDEX, meili, quote } from "@/lib/meili";
import type { Chunk } from "@/lib/types";

/** The passages around a hit: same episode, neighbouring positions, in order. */
export async function GET(req: Request) {
  const url = new URL(req.url);
  const episodeId = url.searchParams.get("episodeId") ?? "";
  const position = Number(url.searchParams.get("position") ?? 0);
  const radius = Math.min(Number(url.searchParams.get("radius") ?? 2), 10);

  const res = await meili.index<Chunk>(CHUNKS_INDEX).search("", {
    filter: [`episodeId = ${quote(episodeId)}`, `position ${position - radius} TO ${position + radius}`],
    sort: ["position:asc"],
    limit: radius * 2 + 1,
  });
  return NextResponse.json(res.hits);
}

import { NextResponse } from "next/server";
import type { MultiSearchResponse } from "meilisearch";
import { CHUNKS_INDEX, EMBEDDER, EPISODES_INDEX, meili, quote, semanticReady } from "@/lib/meili";
import { type ChunkHit, type Episode, SEMANTIC_RATIO, type SearchRequest, type SearchResponse } from "@/lib/types";

const HITS_PER_PAGE = 15;

const SORTS: Record<SearchRequest["sort"], string[] | undefined> = {
  relevance: undefined,
  newest: ["episodeNumber:desc", "start:asc"],
  oldest: ["episodeNumber:asc", "start:asc"],
};

function buildFilter(body: SearchRequest): string[] {
  const out: string[] = [];
  if (body.speaker === "lex") out.push("isLex = true");
  if (body.speaker === "guest") out.push("isLex = false");
  if (body.guests.length) out.push(`guest IN [${body.guests.map(quote).join(", ")}]`);
  if (body.episodeId) out.push(`episodeId = ${quote(body.episodeId)}`);
  return out;
}

export async function POST(req: Request) {
  const body = (await req.json()) as SearchRequest;
  const q = body.q.trim();
  const useHybrid = !!q && (await semanticReady());
  const filter = buildFilter(body);
  const episodeQuery = q
    ? [{ indexUid: EPISODES_INDEX, q, limit: 4, attributesToSearchOn: ["guest"], rankingScoreThreshold: 0.9 }]
    : [];
  // With distinct, facets are counted per episode kept: a facet-only query without distinct
  // gives how many passages match in each episode.
  const countQuery =
    body.distinct && q ? [{ indexUid: CHUNKS_INDEX, q, filter, limit: 0, facets: ["episodeId"] }] : [];

  // One round-trip: transcript chunks (+ facets) and the episodes matching the query.
  const res = await meili.multiSearch({
    queries: [
      {
        indexUid: CHUNKS_INDEX,
        q,
        filter,
        distinct: body.distinct ? "episodeId" : undefined,
        sort: SORTS[body.sort],
        facets: ["guest", "isLex", "source"],
        hitsPerPage: HITS_PER_PAGE,
        page: body.page,
        hybrid: useHybrid ? { embedder: EMBEDDER, semanticRatio: SEMANTIC_RATIO } : undefined,
        attributesToHighlight: ["text", "chapter"],
        attributesToCrop: ["text:60"],
        cropMarker: "…",
        highlightPreTag: "__HL__",
        highlightPostTag: "__/HL__",
        showRankingScore: true,
        // Tells, per hit, whether keywords or embeddings ranked it (shown on hover in the UI).
        showRankingScoreDetails: true,
      },
      ...episodeQuery,
      ...countQuery,
    ],
  }).catch((e: { cause?: { code?: string } }) => {
    // The indexes are created by `pnpm data:setup`; until then the archive is still loading.
    if (e.cause?.code === "index_not_found") return null;
    throw e;
  });
  if (!res) return NextResponse.json({ error: "loading" }, { status: 503 });
  const { results } = res as MultiSearchResponse;

  const chunks = results[0];
  const response: SearchResponse & { semantic: boolean } = {
    hits: chunks.hits as ChunkHit[],
    totalHits: chunks.totalHits ?? chunks.estimatedTotalHits ?? 0,
    totalPages: chunks.totalPages ?? 1,
    page: chunks.page ?? 1,
    processingTimeMs: chunks.processingTimeMs,
    facetDistribution: chunks.facetDistribution ?? {},
    semanticHitCount: (chunks as { semanticHitCount?: number }).semanticHitCount,
    episodes: (episodeQuery.length ? results[1].hits : []) as Episode[],
    momentsPerEpisode: countQuery.length ? results.at(-1)?.facetDistribution?.episodeId : undefined,
    semantic: useHybrid,
  };
  return NextResponse.json(response);
}

import { generateTenantToken } from "meilisearch/token";
import { CHAT_MODEL, CHAT_WORKSPACE, chatEnabled, CHUNKS_INDEX, getChatKey, MEILI_PUBLIC_URL, quote } from "@/lib/meili";
import type { ChatSession } from "@/lib/chat-types";

/**
 * Hands the browser what it needs to call Meilisearch `/chats` directly: a
 * short-lived tenant token derived from the chat key. Its search rules restrict
 * the chat to the chunks index and, optionally, to one episode — the LLM can only
 * retrieve those passages. The chat key itself never leaves the server.
 */
export async function POST(req: Request) {
  const { episodeId } = (await req.json()) as { episodeId?: string };

  const chatKey = (await chatEnabled()) ? await getChatKey() : null;
  if (!chatKey) {
    return Response.json(
      { error: "Chat is not configured. Set CHAT_API_KEY in .env and run `pnpm data:setup`." },
      { status: 503 },
    );
  }

  const token = await generateTenantToken({
    apiKey: chatKey.key,
    apiKeyUid: chatKey.uid,
    searchRules: { [CHUNKS_INDEX]: episodeId ? { filter: `episodeId = ${quote(episodeId)}` } : {} },
    expiresAt: new Date(Date.now() + 30 * 60 * 1000),
  });

  const session: ChatSession = { host: MEILI_PUBLIC_URL, workspace: CHAT_WORKSPACE, model: CHAT_MODEL, token };
  return Response.json(session);
}

